57	\begin{proposition}[Exposure Variation Necessary]
58	\label{prop:exposure_variation}
59	If $e_i = e$ for all $i$ (constant exposure), then $c_n$ and $\theta_n$ are not separately identifiable.
60	\end{proposition}
